import json, pathlib, time, uuid

PENDING = pathlib.Path("pending_review")
STALE_AFTER = 24 * 3600

def park_for_human(item):
    PENDING.mkdir(exist_ok=True)
    body = {"item": item, "queued_at": time.time()}
    (PENDING / f"{uuid.uuid4()}.json").write_text(json.dumps(body))

def queue_health():
    now = time.time()
    ages = [now - json.loads(p.read_text())["queued_at"] for p in PENDING.glob("*.json")]
    return {"backlog_size": len(ages), "oldest_pending": max(ages, default=0)}

def expire_pending():
    for p in PENDING.glob("*.json"):
        queued = json.loads(p.read_text())["queued_at"]
        if time.time() - queued > STALE_AFTER:
            escalate_stale(p)

def escalate_stale(path):
    print(f"unread past review_deadline, applying declared default: {path}")
